import { GENERATION_PROFILES, recommendGenerationProfile, defaultGenerationSeed } from './planetary-generation-profiles.js';
import { GENERATION_MAP_MODES, generationMapData } from './planetary-generation-colors.js';
import { resolvedSurfaceCell } from './planetary-surface-model.js';
import { RESOURCE_DEFINITIONS, popToPersons, personsToPOP } from './resource-definitions.js';
const $=s=>document.querySelector(s);
const download=(name,data)=>{const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);};
export class PlanetaryGenerationUI {
 constructor(surface){this.surface=surface;this.preview=null;this.worker=null;this.serial=0;this.selected=new Set();this.abort=new AbortController();const options={signal:this.abort.signal};
  $('#generation-profile').replaceChildren(...Object.entries(GENERATION_PROFILES).map(([id,p])=>new Option(p.name,id)));
  $('#generation-map-mode').replaceChildren(...Object.entries(GENERATION_MAP_MODES).map(([id,label])=>new Option(label,id)));
  $('#surface-generation-toggle').addEventListener('click',()=>this.open(),options);$('#generation-close').addEventListener('click',()=>this.close(),options);
  $('#generation-preview').addEventListener('click',()=>this.makePreview(),options);$('#generation-apply').addEventListener('click',()=>this.apply(),options);
  $('#generation-cancel').addEventListener('click',()=>{this.invalidate();this.status('미리보기를 취소했습니다. 저장 원본은 유지됩니다.');this.refreshMap();},options);
  $('#generation-undo').addEventListener('click',()=>{try{this.invalidate();const saved=surface.drafts.undo(surface.entry);this.refreshMap();this.status(saved?'마지막 적용을 되돌렸습니다. 현재 탭에만 유지됩니다.':'되돌림은 메모리에만 유지됩니다. JSON으로 백업하세요.');}catch(e){this.status(e.message);}},options);
  $('#generation-export').addEventListener('click',()=>surface.exportCurrent(),options);
  $('#generation-sidecar').addEventListener('click',()=>{if(this.lastMetadata&&surface.isDeveloper())download(`SPACE_generation_${surface.entry.grid.systemId}_${surface.entry.body.id}.json`,this.lastMetadata);},options);
  $('#generation-new-seed').addEventListener('click',()=>{const input=$('#generation-seed');input.value=input.value+':next';this.invalidate();this.status('새 시드가 설정되었습니다. 다시 미리보기 하세요.');},options);
  $('#generation-add-selected').addEventListener('click',()=>{if(surface.selectedId)this.selected.add(surface.selectedId);this.selectionSummary();this.invalidate();},options);
  $('#generation-clear-selected').addEventListener('click',()=>{this.selected.clear();this.selectionSummary();this.invalidate();},options);
  $('#generation-map-mode').addEventListener('change',()=>this.refreshMap(),options);
  $('#generation-confirm').addEventListener('change',()=>this.updateApply(),options);
  $('#generation-form').addEventListener('input',event=>{if(!['generation-map-mode','generation-multiselect','generation-confirm'].includes(event.target.id)){this.invalidate();this.refreshMap();}},options);
  $('#generation-form').addEventListener('submit',e=>e.preventDefault(),options);
 }
 open(){const s=this.surface;if(!s.entry||!s.isDeveloper())return;this.close();s.resources?.close();s.closeEditor();$('#surface-io').hidden=true;$('#surface-info').hidden=true;$('#generation-panel').hidden=false;const {body,grid}=s.entry,recommended=recommendGenerationProfile(body);this.openEntry=s.entry;
  $('#generation-title').textContent=body.name+' · 자동 설정';$('#generation-profile').value=recommended.id;$('#generation-reason').textContent=recommended.reason+' · 수치는 조정 가능한 게임 초기 가정';$('#generation-seed').value=defaultGenerationSeed(grid.systemId,body.id);$('#generation-scope').value='all';$('#generation-policy').value='fill-unset';$('#generation-population').value='';$('#generation-civilization').value='';$('#generation-land-target').value='';$('#generation-temperature').value='';$('#generation-urban-policy').value='none';$('#generation-earth-source').checked=!!body.surfaceLandMaskPath;$('#generation-earth-source').disabled=!body.surfaceLandMaskPath;$('#generation-multiselect').checked=false;$('#generation-center').checked=false;
  for(const input of document.querySelectorAll('[data-generation-field]'))input.checked=true;
  $('#generation-resource-inputs').replaceChildren(...[...RESOURCE_DEFINITIONS.values()].filter(r=>r.naturalDeposit&&r.unit==='U').map(r=>{const label=document.createElement('label');label.textContent=r.name+' · 행성 전체 목표 U (빈칸=미정, 0=없음 확정)';const input=document.createElement('input');input.type='text';input.inputMode='decimal';input.dataset.resourceBudget=r.id;input.id='generation-budget-'+r.id;label.append(input);return label;}));
  this.selected.clear();this.lastMetadata=null;this.selectionSummary();this.status('미설정만 채우기가 기본입니다. 인구·자원 총량은 확정값이 없으므로 빈칸입니다.');this.refreshMap();
 }
 invalidate(){this.serial++;this.worker?.terminate();this.worker=null;this.preview=null;$('#generation-confirm').checked=false;$('#generation-apply').disabled=true;$('#generation-summary').textContent='';$('#generation-comparison').textContent='';$('#generation-preview').disabled=false;}
 close(){this.invalidate();this.surface.distributions?.release('generation');$('#generation-panel').hidden=true;$('#generation-legend').hidden=true;$('#generation-legend-text').textContent='';$('#generation-legend-categories').replaceChildren();$('#generation-status').textContent='';$('#generation-form').reset();$('#generation-resource-inputs').replaceChildren();this.selected.clear();this.openEntry=null;this.lastMetadata=null;this.lastMap=null;this.surface.renderInfo();}
 selectionSummary(){$('#generation-selected-count').textContent=`선택 ${this.selected.size}구역`;}
 onSelection(id){if($('#generation-panel').hidden)return;if(id&&$('#generation-multiselect').checked){if(this.selected.has(id))this.selected.delete(id);else this.selected.add(id);this.selectionSummary();this.invalidate();this.refreshMap();}this.compareCell();}
 settings(){const s=this.surface,entry=s.entry,parameters={};for(const [id,key]of [['generation-land-target','landTarget'],['generation-temperature','temperatureK']])if($('#'+id).value.trim()!=='')parameters[key]=Number($('#'+id).value);
  const budgets={};for(const input of document.querySelectorAll('[data-resource-budget]')){const text=input.value.trim();if(text&&!/^\d+(\.\d{1,3})?$/.test(text))throw Error('U는 음이 아닌 수, 소수 3자리까지 입력하세요.');budgets[input.dataset.resourceBudget]=text===''?null:Number(text);}
  return {generation:{systemId:entry.grid.systemId,body:entry.body,grid:entry.grid,seed:$('#generation-seed').value,profileId:$('#generation-profile').value,parameters,resourceBudgetsU:budgets,scenario:{populationTotalPersons:popToPersons($('#generation-population').value),civilizationId:$('#generation-civilization').value.trim()||null,urbanizationPolicy:$('#generation-urban-policy').value,settlementTileIds:$('#generation-center').checked&&s.selectedId?[s.selectedId]:[]}},planning:{template:entry.template,scope:$('#generation-scope').value,selectedIds:[...this.selected],fields:[...document.querySelectorAll('[data-generation-field]:checked')].map(i=>i.dataset.generationField),policy:$('#generation-policy').value}};
 }
 async makePreview(){if(!this.surface.entry||!this.surface.isDeveloper()||$('#generation-panel').hidden)return;this.invalidate();const token=this.serial,entry=this.surface.entry;$('#generation-preview').disabled=true;this.status('작업 스레드에서 계산 중…');try{const input=this.settings();if($('#generation-earth-source').checked&&entry.body.surfaceLandMaskPath){const response=await fetch(entry.body.surfaceLandMaskPath);if(!response.ok)throw Error('육지 경계 자료를 읽지 못했습니다. 절차적 모드로 전환할 수 있습니다.');input.generation.earthMask=await response.json();}
   if(token!==this.serial||entry!==this.surface.entry)return;const worker=new Worker(new URL('./planetary-generation-worker.js',import.meta.url),{type:'module'});this.worker=worker;
   worker.onerror=event=>{if(token===this.serial){this.status('생성 거부: '+event.message);$('#generation-preview').disabled=false;}worker.terminate();if(this.worker===worker)this.worker=null;};
   worker.onmessage=event=>{worker.terminate();if(this.worker===worker)this.worker=null;if(token!==this.serial||entry!==this.surface.entry||!this.surface.isDeveloper())return;$('#generation-preview').disabled=false;if(!event.data.ok){this.status('생성 거부: '+event.data.error);return;}this.preview=event.data.preview;this.preview.settings.parameters=input.generation.parameters;this.renderPreview();};worker.postMessage(input);
  }catch(error){if(token===this.serial){this.status('생성 거부: '+error.message);$('#generation-preview').disabled=false;}}
 }
 renderPreview(){const p=this.preview,s=p.summary;$('#generation-summary').textContent=`대상 ${p.targetCellCount}셀 · 작성 예정 ${p.changedCells}셀 / ${p.changedFields}필드 · 보호 ${p.protectedValues}값\n광석 ${(s.resourceQuantaTotals.ore??0)/1000} U · 매장지 ${s.depositCount}개 · 총 ${personsToPOP(s.populationPersons)} POP (${s.populationPersons}명, 인구 설정 ${s.populationConfiguredCells}셀)\n출처: ${p.source.label}\n기반: ${this.surface.entry.source??'현재 로컬/메모리 초안'}\n${p.warnings.join('\n')}`;this.status('미리보기 완료 · 아직 적용/저장하지 않았습니다. 지도 색과 변경값을 검토하세요.');this.updateApply();this.refreshMap();}
 updateApply(){$('#generation-apply').disabled=!this.preview||!$('#generation-confirm').checked;}
 refreshMap(){if($('#generation-panel').hidden||!this.surface.entry||!this.surface.isDeveloper())return;const entry=this.surface.entry,template=this.preview?.nextTemplate??entry.template,map=generationMapData(template,entry.grid,entry.body,$('#generation-map-mode').value);if(this.lastMap?.template!==template||this.lastMap?.mode!==$('#generation-map-mode').value||this.lastMap?.view!==this.surface.viewer.surface){this.surface.distributions.setDeveloperLayer('generation',map.colors);this.lastMap={template,mode:$('#generation-map-mode').value,view:this.surface.viewer.surface};}const legend=$('#generation-legend');legend.hidden=false;$('#generation-legend-text').textContent=`개발자 원본 · ${this.preview?'적용 예정':'현재 원본'} · ${GENERATION_MAP_MODES[$('#generation-map-mode').value]} · ${$('#generation-map-mode').value==='population'?'POP':map.unit}\n${map.min===null?'숫자 범위 없음':`min ${$('#generation-map-mode').value==='population'?personsToPOP(map.min):map.min} / max ${$('#generation-map-mode').value==='population'?personsToPOP(map.max):map.max}`} · 회색=미설정 null (${map.nullCount}셀) · 남색=0`;const gradient=legend.querySelector('.generation-gradient');gradient.hidden=['terrain','ore','population'].includes($('#generation-map-mode').value);gradient.style.background=$('#generation-map-mode').value==='land'?'linear-gradient(90deg,#235ca7,#80be64)':'linear-gradient(90deg,#1a3e5f,#f4be55)';const categories=$('#generation-legend-categories');categories.replaceChildren(...(map.legend??[]).map(item=>{const span=document.createElement('span'),swatch=document.createElement('i');swatch.style.background=item.color;span.append(swatch,document.createTextNode(item.name));return span;}));this.compareCell();}
 compareCell(){const s=this.surface,id=s.selectedId;if(!id||!s.entry||$('#generation-panel').hidden){$('#generation-comparison').textContent='지도에서 구역을 선택하면 이전값 / 예정값을 비교합니다.';return;}const before=resolvedSurfaceCell(s.entry.template,s.entry.grid,s.entry.body,id),after=this.preview?resolvedSurfaceCell(this.preview.nextTemplate,s.entry.grid,s.entry.body,id):before;const brief=c=>({terrain:c.geology.terrain,environment:c.geology.environment,deposits:c.geology.deposits,populationPersons:c.scenario.populationPersons,urbanizationRate:c.scenario.urbanizationRate,infrastructureLevel:c.scenario.infrastructureLevel});$('#generation-comparison').textContent=id+'\n이전(현재 원본):\n'+JSON.stringify(brief(before),null,2)+'\n예정:\n'+JSON.stringify(brief(after),null,2);}
 apply(){const s=this.surface,p=this.preview;if(!p||!s.entry||!s.isDeveloper()||!$('#generation-confirm').checked)return;try{if(s.entry!==this.openEntry||JSON.stringify(s.entry.template)!==p.baseJSON)throw Error('원본이 변경되었습니다. 다시 미리보기 하세요.');
   const metadata={kind:'planetary-generation',metadataVersion:1,systemId:s.entry.grid.systemId,bodyId:s.entry.body.id,gridFingerprint:s.entry.grid.gridFingerprint,...p.settings,source:p.source};
   if(p.policy==='overwrite'&&!s.drafts.transient)download(`SPACE_surface_before_generation_${s.entry.grid.systemId}_${s.entry.body.id}.json`,s.entry.template);
   const saved=s.drafts.commit(s.entry,p.nextTemplate,{replace:p.policy==='overwrite'});this.lastMetadata=metadata;this.invalidate();this.refreshMap();this.status(saved?'적용하고 현재 탭에 유지합니다. 되돌리기·수동 JSON 내보내기가 가능합니다.':'메모리에 적용했습니다. 저장 실패: JSON으로 백업하세요.');
  }catch(error){this.status('적용 거부: '+error.message);}
 }
 status(message){$('#generation-status').textContent=message;$('#generation-status').title=message;}
 dispose(){this.close();this.abort.abort();}
}
